def call_moe_router(system: str, prompt: str, timeout: int = 120) -> Optional[str]:
    """Call Arsify MoE Router :8002 with correct format."""
    moe_url = os.getenv("MOE_ROUTER_URL", "http://localhost:8002")
    try:
        import httpx
        # MoE Router expects: message (string), model, stream
        full_message = f"{system}\n\n{prompt}"
        r = httpx.post(f"{moe_url}/chat", json={
            "message": full_message,
            "model": os.getenv("MOE_MODEL", "phi3:mini"),
            "stream": False
        }, timeout=timeout)
